-- 各城市知识库酒店（经济/舒适/高端三档，ticket_price 为每晚单间基准价，幂等可重复执行）
INSERT INTO poi_knowledge (city, name, category, address, latitude, longitude,
                           ticket_price, duration_min, open_time, tags, rating, description)
SELECT t.city, t.name, t.category, t.address, t.latitude, t.longitude,
       t.ticket_price, t.duration_min, t.open_time, t.tags, t.rating, t.description
FROM (
  SELECT '北京' AS city,'如家精选酒店前门店' AS name,'hotel' AS category,'东城区煤市街33号' AS address,39.892180 AS latitude,116.390210 AS longitude,300.00 AS ticket_price,NULL AS duration_min,'14:00后入住' AS open_time,'住宿' AS tags,4.5 AS rating,'经济型连锁，天安门/大栅栏步行可达，适合预算有限出行。' AS description
  UNION ALL SELECT '北京','全季酒店王府井店','hotel','东城区金鱼胡同18号',39.913610,116.411230,480.00,NULL,'14:00后入住','住宿',4.7,'舒适型中端商务，王府井核心地段近地铁。'
  UNION ALL SELECT '北京','北京贵宾楼饭店','hotel','东城区金鱼胡同3号',39.915060,116.412870,980.00,NULL,'14:00后入住','住宿',4.8,'高端老牌五星，故宫东侧皇城地段。'
  UNION ALL SELECT '上海','汉庭酒店南京路步行街店','hotel','黄浦区山东中路311号',31.235420,121.484130,320.00,NULL,'14:00后入住','住宿',4.5,'经济型连锁，步行至外滩约10分钟。'
  UNION ALL SELECT '上海','全季酒店人民广场店','hotel','黄浦区九江路595号',31.233860,121.473840,520.00,NULL,'14:00后入住','住宿',4.7,'舒适型中端商旅，人民广场地铁枢纽。'
  UNION ALL SELECT '上海','上海和平饭店','hotel','黄浦区南京东路20号',31.241890,121.490330,1350.00,NULL,'14:00后入住','住宿',4.9,'外滩万国建筑博览群地标高端酒店。'
  UNION ALL SELECT '杭州','汉庭酒店西湖断桥店','hotel','拱墅区湖墅南路111号',30.265430,120.152340,290.00,NULL,'14:00后入住','住宿',4.5,'经济型连锁，距断桥残雪步行可达。'
  UNION ALL SELECT '杭州','杭州湖滨银泰in77亚朵酒店','hotel','上城区延安路258号',30.250951,120.163052,480.00,NULL,'14:00后入住','住宿',4.8,'舒适型中端湖滨商圈，近西湖东岸。'
  UNION ALL SELECT '杭州','杭州西子宾馆汪庄','hotel','西湖区南山路37号',30.226050,120.146720,1250.00,NULL,'14:00后入住','住宿',4.9,'国宾馆级园林酒店私享西湖一线湖景。'
  UNION ALL SELECT '成都','如家商旅春熙路店','hotel','锦江区中新街58号',30.653860,104.081570,240.00,NULL,'14:00后入住','住宿',4.5,'经济型连锁，春熙路太古里核心商圈。'
  UNION ALL SELECT '成都','成都太古里亚朵酒店','hotel','锦江区东大街上东大街段176号',30.651730,104.083890,430.00,NULL,'14:00后入住','住宿',4.7,'舒适型中端，地铁口直达太古里。'
  UNION ALL SELECT '成都','成都博舍酒店','hotel','锦江区笔帖式街81号',30.652980,104.081260,1150.00,NULL,'14:00后入住','住宿',4.9,'高端设计精品酒店，由百年笔帖式老院落改建。'
  UNION ALL SELECT '西安','如家酒店钟楼店','hotel','碑林区南大街2号',34.260310,108.942380,230.00,NULL,'14:00后入住','住宿',4.5,'经济型连锁，钟鼓楼广场近在咫尺。'
  UNION ALL SELECT '西安','西安钟楼亚朵酒店','hotel','碑林区南大街30号',34.261020,108.942850,400.00,NULL,'14:00后入住','住宿',4.7,'舒适型中端，回民街与钟楼步行圈。'
  UNION ALL SELECT '西安','西安索菲特传奇酒店','hotel','新城区东新街199号',34.266840,108.961220,820.00,NULL,'14:00后入住','住宿',4.8,'高端法式传奇五星，五环集团经典物业。'
  UNION ALL SELECT '三亚','三亚湾红树林度假世界木棉店','hotel','天涯区三亚湾路155号',18.271860,109.488970,450.00,NULL,'14:00后入住','住宿',4.6,'度假综合体经济档，亲子设施丰富。'
  UNION ALL SELECT '三亚','大东海银泰阳光度假酒店','hotel','吉阳区大东海旅游区海韵路',18.213740,109.513280,620.00,NULL,'14:00后入住','住宿',4.7,'舒适型海滨度假，私家沙滩泳池。'
  UNION ALL SELECT '三亚','亚龙湾美高梅度假酒店','hotel','吉阳区亚龙湾国家旅游区',18.196670,109.636110,1450.00,NULL,'14:00后入住','住宿',4.8,'高端滨海度假五星，亚龙湾细沙海滩。'
) t
WHERE NOT EXISTS (SELECT 1 FROM poi_knowledge WHERE category = 'hotel');
